export type Lang = 'en' | 'hi' | 'ar' | 'zh' | 'fr' | 'de' | 'es' | 'ru' | 'ja' | 'ko' | 'pt' | 'it';

export const SUPPORTED_LANGS: { code: Lang; name: string; flag: string; voice: string }[] = [
  { code: 'en', name: 'English',    flag: '🇬🇧', voice: 'en-IN' },
  { code: 'hi', name: 'हिन्दी',      flag: '🇮🇳', voice: 'hi-IN' },
  { code: 'ar', name: 'العربية',    flag: '🇸🇦', voice: 'ar-SA' },
  { code: 'zh', name: '中文',        flag: '🇨🇳', voice: 'zh-CN' },
  { code: 'fr', name: 'Français',   flag: '🇫🇷', voice: 'fr-FR' },
  { code: 'de', name: 'Deutsch',    flag: '🇩🇪', voice: 'de-DE' },
  { code: 'es', name: 'Español',    flag: '🇪🇸', voice: 'es-ES' },
  { code: 'ru', name: 'Русский',    flag: '🇷🇺', voice: 'ru-RU' },
  { code: 'ja', name: '日本語',      flag: '🇯🇵', voice: 'ja-JP' },
  { code: 'ko', name: '한국어',      flag: '🇰🇷', voice: 'ko-KR' },
  { code: 'pt', name: 'Português',  flag: '🇧🇷', voice: 'pt-BR' },
  { code: 'it', name: 'Italiano',   flag: '🇮🇹', voice: 'it-IT' },
]

export const RTL_LANGS: Lang[] = ['ar']
export const isRTL = (lang: string) => RTL_LANGS.includes(lang as Lang)
export const getVoiceCode = (lang: string) =>
  SUPPORTED_LANGS.find(l => l.code === lang)?.voice ?? 'en-IN'

