// Translate a UI key with optional variable interpolation
export function t(lang: string, key: string, vars: Record<string, string> = {}): string {
  const l = (SUPPORTED_LANGS.some(x => x.code === lang) ? lang : 'en') as Lang
  let str = UI[l][key] ?? UI['en'][key] ?? key
  for (const [k, v] of Object.entries(vars)) {
    str = str.replace(new RegExp(`\\{${k}\\}`, 'g'), v)
  }
  return str
}

// Read/write language from localStorage
export const LANG_KEY = 'guest_lang'
export const getLang = (): string => localStorage.getItem(LANG_KEY) ?? 'en'
export const setLang = (lang: string) => localStorage.setItem(LANG_KEY, lang)
